import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        int[][] a = parseMatrix(line);
        int n = a.length;
        if (n == 0) {
            System.out.println(0);
            return;
        }
        long sum = 0;
        for (int i = 0; i < n; i++) {
            sum += a[i][i];
            sum += a[i][n - 1 - i];
        }
        if (n % 2 == 1) sum -= a[n / 2][n / 2];
        System.out.println(sum);
    }

    static int[][] parseMatrix(String s) {
        List<int[]> rows = new ArrayList<>();
        List<Integer> cur = new ArrayList<>();
        int depth = 0;
        int i = 0;
        while (i < s.length()) {
            char c = s.charAt(i);
            if (c == '[') {
                depth++;
                if (depth == 2) cur = new ArrayList<>();
                i++;
            } else if (c == ']') {
                if (depth == 2) {
                    int[] row = new int[cur.size()];
                    for (int j = 0; j < row.length; j++) row[j] = cur.get(j);
                    rows.add(row);
                }
                depth--;
                i++;
            } else if (c == '-' || (c >= '0' && c <= '9')) {
                int sign = 1;
                if (c == '-') {
                    sign = -1;
                    i++;
                }
                long val = 0;
                while (i < s.length() && s.charAt(i) >= '0' && s.charAt(i) <= '9') {
                    val = val * 10 + (s.charAt(i) - '0');
                    i++;
                }
                cur.add((int) (sign * val));
            } else {
                i++;
            }
        }
        int[][] res = new int[rows.size()][];
        for (int j = 0; j < res.length; j++) res[j] = rows.get(j);
        return res;
    }
}

